#include <sys/stat.h>
#include <sys/time.h>
#include <sys/attr.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdio.h>
#include <stdlib.h>
#include <errno.h>
#include <dlfcn.h>
#include <time.h>
#include <assert.h>
static int failures;
static void observe(const char *name, int result, int fd, const struct timespec t[2]) {
 int saved=errno; struct stat s; assert(fstat(fd,&s)==0);
 int okay=result==0 && s.st_atimespec.tv_sec==t[0].tv_sec && s.st_atimespec.tv_nsec==t[0].tv_nsec && s.st_mtimespec.tv_sec==t[1].tv_sec && s.st_mtimespec.tv_nsec==t[1].tv_nsec;
 printf("TIMESTAMP_CASE %s result=%d errno=%d atime=%lld.%09ld mtime=%lld.%09ld exact=%d\n",name,result,saved,(long long)s.st_atimespec.tv_sec,s.st_atimespec.tv_nsec,(long long)s.st_mtimespec.tv_sec,s.st_mtimespec.tv_nsec,okay); failures+=!okay;
}
int main(int argc,char **argv) {
 assert(argc==3); setbuf(stdout,NULL); alarm(20);
 char path[4096];snprintf(path,sizeof(path),"%s/file",argv[1]);int fd=open(path,O_RDWR|O_CREAT|O_EXCL,0600);assert(fd>=0);
 struct timespec t[2]={{1600000000,123456700},{1700000000,765432100}};
 errno=0; int ret=utimensat(AT_FDCWD,path,t,0);observe("utimensat-follow",ret,fd,t);
 errno=0; ret=utimensat(AT_FDCWD,path,t,AT_SYMLINK_NOFOLLOW);observe("utimensat-nofollow",ret,fd,t);
 errno=0; ret=futimens(fd,t);observe("futimens",ret,fd,t);
 void *h=dlopen(argv[2],RTLD_LAZY|RTLD_LOCAL);assert(h);int(*native_path)(const char*,const struct timespec*)=dlsym(h,"SystemNative_UTimensat");int(*native_fd)(intptr_t,const struct timespec*)=dlsym(h,"SystemNative_FUTimens");assert(native_path&&native_fd);
 errno=0;ret=native_path(path,t);observe("original-dotnet-UTimensat",ret,fd,t);
 errno=0;ret=native_fd(fd,t);observe("original-dotnet-FUTimens",ret,fd,t);
 struct timespec omitted[2]={{0,UTIME_OMIT},{1700000002,999999900}};
 t[1]=omitted[1];errno=0;ret=native_path(path,omitted);observe("original-dotnet-omit-access",ret,fd,t);
 struct attrlist attrs={.bitmapcount=ATTR_BIT_MAP_COUNT,.commonattr=ATTR_CMN_CRTIME};
 errno=0;ret=setattrlist(path,&attrs,&t[1],sizeof(t[1]),0);printf("TIMESTAMP_CREATION_UNSUPPORTED result=%d errno=%d\n",ret,errno); failures+=!(ret==-1 && errno==ENOTSUP);
 struct timeval tv[2]={{1600000001,123456},{1700000001,765432}};t[0]=(struct timespec){tv[0].tv_sec,tv[0].tv_usec*1000};t[1]=(struct timespec){tv[1].tv_sec,tv[1].tv_usec*1000};
 errno=0;ret=futimes(fd,tv);observe("futimes-microseconds",ret,fd,t);
 struct stat before,after;assert(fstat(fd,&before)==0);
 tv[1].tv_usec=1000000;errno=0;ret=futimes(fd,tv);int saved=errno;assert(fstat(fd,&after)==0);
 int invalid=ret==-1&&saved==EINVAL&&before.st_mtimespec.tv_sec==after.st_mtimespec.tv_sec&&before.st_mtimespec.tv_nsec==after.st_mtimespec.tv_nsec&&before.st_atimespec.tv_sec==after.st_atimespec.tv_sec&&before.st_atimespec.tv_nsec==after.st_atimespec.tv_nsec;failures+=!invalid;printf("TIMESTAMP_INVALID_MICROSECONDS_REJECTED %d\n",invalid);
 time_t lower=time(NULL);errno=0;ret=futimes(fd,NULL);assert(fstat(fd,&after)==0);int now=ret==0&&after.st_mtimespec.tv_sec>=lower&&after.st_mtimespec.tv_sec<=time(NULL)&&after.st_atimespec.tv_sec>=lower&&after.st_atimespec.tv_sec<=time(NULL);failures+=!now;printf("TIMESTAMP_NULL_NOW %d\n",now);
 close(fd);unlink(path);printf("TIMESTAMP_FAILURES %d\n",failures);return 0;
}
